			fFirst := fNames[0]
			fLast := ""
			if len(fNames) == 2 {
				fLast = fNames[1]
			}
			relatives = append(relatives, Relative{
				FirstName:    fFirst,
				LastName:     fLast,
				Relationship: "Father",
			})
		}

		// Mother
		mother := record[4]
		if mother != "null" && mother != "" {
			mNames := strings.SplitN(mother, " ", 2)
			mFirst := mNames[0]
			mLast := ""
			if len(mNames) == 2 {
				mLast = mNames[1]
			}
			relatives = append(relatives, Relative{
