				motherLast := motherParts[len(motherParts)-1]
				relatives = append(relatives, Relative{
					FirstName:    motherFirst,
					LastName:     motherLast,
					Relationship: "Mother",
				})
			} else if len(motherParts) == 1 {
				relatives = append(relatives, Relative{
					FirstName:    motherParts[0],
					LastName:     "",
					Relationship: "Mother",
				})
			}
		}

		// Brother
